      [266]={["bonuses"]={[1]={["description"]="(1 предмет) Пробивание +|cffffff1435|r",["index"]=1,["perfected"]=false,["required"]=1,},[2]={["description"]="(2 предмета) При нанесении урона вы с вероятностью |cffffff10%|r призываете призрачные конечности дреуга, которые создают перед вами ударные волны, наносящие |cffffff1 224|r ед. физического урона раз в |cffffff0,6|r сек. в течение |cffffff2,4|r сек. Этот эффект может срабатывать не чаще чем раз в |cffffff6|r сек., а его сила зависит от вашей силы оружия или заклинаний (учитывается характеристика с более высоким значением).",["index"]=2,["perfected"]=false,["required"]=2,},},["familyId"]=266,["icon"]="/esoui/art/icons/gear_undaunteddreugh_head_a.dds",["id"]=266,["max"]=2,["name"]="Кра'гх",["normal"]=1,["perfected"]=0,},
      [694]={["bonuses"]={[1]={["description"]="(1 предмет) Пробивание +|cffffff1650|r",["index"]=1,["perfected"]=false,["required"]=1,},[2]={["description"]="(1 предмет) Урон, наносимый монстрам, увеличивается на |cffffff15%|r. Вы получаете постоянный эффект «Малая сила», увеличивающий ваш критический урон на |cffffff10%|r, а общий урон от ваших обычных и силовых атак уменьшается на |cffffff99%|r.",["index"]=2,["perfected"]=false,["required"]=1,},},["familyId"]=694,["icon"]="/esoui/art/icons/u38_antiquities_goldandblueshalknecklace.dds",["id"]=694,["max"]=1,["name"]="Амулет велотийского ур-мага",["normal"]=1,["perfected"]=0,},
      [809]={["bonuses"]={[1]={["description"]="(2 предмета) Сила оружия и заклинаний +|cffffff124|r",["index"]=1,["perfected"]=false,["required"]=2,},[2]={["description"]="(3 предмета) Шанс крит. удара +|cffffff634|r",["index"]=2,["perfected"]=false,["required"]=3,},[3]={["description"]="(4 предмета) Пробивание +|cffffff1435|r",["index"]=3,["perfected"]=false,["required"]=4,},[4]={["description"]="(5 предметов) Прямой урон, наносимый монстрам, увеличивается на |cffffff15%|r.",["index"]=4,["perfected"]=false,["required"]=5,},},["familyId"]=809,["icon"]="/esoui/art/icons/gear_breton_medium_chest_d.dds",["id"]=809,["max"]=5,["name"]="Ловчий рожденных-приливом",["normal"]=5,["perfected"]=0,},
