      [79]={["classId"]=0,["description"]="Позволяет использовать унции олова.",["earnedRank"]=1,["icon"]="/esoui/art/icons/passive_jewelerengraver.dds",["id"]=103632,["lineActive"]=true,["lineId"]=141,["name"]="Гравер",["passive"]=true,["purchased"]=true,["rank"]=1,["skillType"]=8,["ultimate"]=false,},
